from topics_a import t, T
D='dentist'
t('dentist',D,'a dentist',"Dentists examine, diagnose and treat problems with teeth and gums, from check-ups and fillings to extractions, crowns and preventive care.",["Regular check-ups catch problems early.","Ask for a written treatment plan.","Mention anxiety so the team can help."])
t('private-dentist',D,'a private dentist',"Private dentists offer appointments outside the NHS, often with more time, wider treatment and material choices, and quicker access.",["Membership plans spread routine costs.","Ask for itemised treatment plans.","Check GDC registration."])
t('dental-clinic',D,'a dental clinic',"Dental clinics range from single-dentist practices to large centres with hygienists, specialists and in-house imaging.",["Larger clinics may offer specialists under one roof.","Check opening hours.","Ask about emergency slots."])
t('private-dental-clinic',D,'a private dental clinic',"Private dental clinics provide general and cosmetic dentistry without NHS constraints, often with extended hours.",["Compare membership plans.","Ask about finance options.","Read online reviews carefully."])
t('children-private-dentist',D,'a private dentist for children',"Children's dentists focus on gentle, preventive care, fluoride varnish, fissure sealants and getting children comfortable with visits.",["Start visits early.","NHS dental care is free for under-18s.","Ask about orthodontic assessment."])
t('emergency-dentist',D,'an emergency dentist',"Emergency dentists see urgent problems such as severe toothache, swelling, broken teeth and lost crowns, often the same day.",["Phone first for an urgent slot.","Facial swelling affecting breathing needs A&E.","NHS 111 can direct urgent care."])
t('emergency-dental',D,'emergency dental care',"Emergency dental care treats pain, infection and trauma quickly, then plans follow-up treatment.",["Pain relief may come first.","Keep a knocked-out adult tooth in milk.","Follow up for permanent treatment."])
t('same-day-dentist',D,'a same-day dentist',"Same-day dentists hold appointments for urgent problems booked on the day.",["Call early in the morning.","Describe symptoms clearly.","Same-day crowns are possible in some clinics."])
t('same-day-dental',D,'same-day dental treatment',"Same-day dental appointments cover urgent pain and, in some clinics, same-day crowns made with digital scanning.",["Digital crowns use CAD/CAM.","Not every case suits same-day treatment.","Ask about follow-up."])
t('dental-hygienist',D,'a dental hygienist',"Dental hygienists clean teeth, treat gum disease and give advice on brushing, interdental cleaning and diet; many can be seen directly.",["Direct access to hygienists is allowed.","Regular cleaning prevents gum disease.","Ask about airflow cleaning."])
t('scale-and-polish',D,'a scale and polish',"A scale and polish removes plaque and tartar from teeth, helping prevent gum disease and freshen the mouth.",["Usually done by a hygienist.","Frequency depends on gum health.","Sensitivity after cleaning is common."])
t('gum-disease-treatment',D,'gum disease treatment',"Gum disease treatment ranges from deep cleaning to periodontal therapy and, in advanced cases, specialist care.",["Bleeding gums are an early sign.","Smoking worsens gum disease.","Periodontists are GDC specialists."])
t('root-canal',D,'root canal treatment',"Root canal treatment removes infected or inflamed pulp from inside a tooth, cleans the canals and seals them to save the tooth.",["Endodontists specialise in complex cases.","A crown is often needed afterwards.","Modern anaesthetic keeps it comfortable."])
t('wisdom-tooth-removal',D,'wisdom tooth removal',"Wisdom tooth removal is considered when wisdom teeth cause infection, decay, pain or damage to neighbouring teeth.",["X-rays guide the decision.","Oral surgeons handle complex cases.","Plan a few days of recovery."])
t('crown',D,'a dental crown',"A crown covers a damaged, weakened or root-treated tooth to restore shape, strength and appearance.",["Materials include ceramic, zirconia and metal.","Usually two appointments.","Ask about guarantees."])
t('private-crown',D,'a private crown',"Private crowns offer a wider choice of materials and labs, including highly aesthetic ceramics.",["Ask which lab makes the crown.","Shade matching matters.","Get costs in writing."])
t('bridge',D,'a dental bridge',"A bridge replaces one or more missing teeth by attaching false teeth to neighbouring teeth or implants.",["Adhesive bridges need less preparation.","Clean under bridges carefully.","Compare with implants."])
t('private-bridge',D,'a private dental bridge',"Private bridges use a range of designs and materials, chosen to match your smile and bite.",["Discuss conventional and adhesive designs.","Ask how long bridges typically last.","Check guarantees."])
t('dentures',D,'dentures',"Dentures replace missing teeth with removable plates, either full or partial, made to fit your mouth.",["Implant-retained dentures are more stable.","Adjustments are normal at first.","Clean dentures daily."])
t('private-dentures',D,'private dentures',"Private dentures offer premium materials and more appointments to perfect fit and appearance.",["Clinical dental technicians can make dentures.","Fit affects comfort and speech.","Ask about relines."])
t('dental-implants',D,'dental implants',"Dental implants are titanium or ceramic posts placed in the jaw to support crowns, bridges or dentures replacing missing teeth.",["Bone quality affects suitability.","Treatment takes several months.","Ask about the implant system used."])
t('nervous-patient-dentist',D,'a dentist for nervous patients',"Dentists experienced with anxious patients take extra time, explain each step and may offer sedation.",["Tell the practice about your anxiety.","Agree a stop signal.","Short first visits help."])
t('sedation-dentist',D,'a sedation dentist',"Sedation dentists offer conscious sedation, such as IV or inhalation sedation, for anxious patients or complex treatment.",["You need an escort home after IV sedation.","Medical history is checked.","Sedation is not general anaesthetic."])
t('sedation-dentistry',D,'sedation dentistry',"Sedation dentistry helps anxious patients relax during treatment using IV, oral or inhalation sedation.",["Ask about staff training.","Plan the day around recovery.","Follow pre-sedation instructions."])
t('cosmetic-dentist',D,'a cosmetic dentist',"Cosmetic dentists improve the appearance of teeth with whitening, bonding, veneers, aligners and crowns.",["Health comes before cosmetics.","Ask to see their own cases.","Whitening must be done by a dental professional."])
t('cosmetic-dentistry',D,'cosmetic dentistry',"Cosmetic dentistry covers treatments that change the colour, shape, size or alignment of teeth.",["Minimal treatment preserves tooth structure.","Digital smile previews help decisions.","Results need maintenance."])
t('smile-makeover',D,'a smile makeover',"A smile makeover combines treatments such as aligners, whitening, bonding and veneers to achieve an agreed result.",["Planning comes first.","Treatment sequence matters.","Discuss realistic expectations."])
t('composite-bonding',D,'composite bonding',"Composite bonding adds tooth-coloured resin to reshape teeth, close gaps or repair chips, often in a single visit.",["Bonding can stain over time.","Little or no drilling is needed.","Maintenance appointments help."])
t('veneers',D,'veneers',"Veneers are thin porcelain or composite shells bonded to the front of teeth to change their colour, shape or size.",["Porcelain veneers usually need some enamel removal.","Composite veneers are reversible in some cases.","Ask how long they last."])
t('veneers-dentist',D,'a veneers dentist',"Dentists experienced in veneers plan carefully with photos, mock-ups and bite analysis before preparing teeth.",["Ask for mock-ups.","Check bite assessment.","Ask about replacement costs."])
t('invisalign',D,'Invisalign',"Invisalign is a brand of clear aligner that straightens teeth with a series of removable trays, planned digitally.",["Aligners must be worn most of the day.","Retainers keep results.","Ask about refinements."])
t('invisalign-dentist',D,'an Invisalign dentist',"Invisalign dentists are trained to plan and monitor aligner treatment; experience levels vary.",["Ask how many cases they treat.","Check monitoring arrangements.","Understand what is included."])
t('clear-aligners',D,'clear aligners',"Clear aligners are removable plastic trays that gradually move teeth; a dental examination before starting is essential.",["Avoid treatment without a dentist's examination.","Gum health must be good first.","Retention is lifelong."])
t('orthodontics',D,'orthodontics',"Orthodontics straightens teeth and corrects bites with fixed braces, clear aligners or functional appliances, for children and adults.",["Specialist orthodontists are on a GDC list.","NHS treatment is limited to children with need.","Retainers are essential."])
